<!doctype html><html lang="{{ $site->locale }}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $slots['title'] ?? $site->name }}</title><meta name="description" content="{{ $slots['description'] ?? '' }}">@if(isset($slots['meta_keywords']))<meta name="keywords" content="{{ $slots['meta_keywords'] }}">@endif<link rel="canonical" href="{{ $canonicalUrl }}">@if($view === 'search')<meta name="robots" content="noindex,follow">@endif<style>{!! App\Domain\Publishing\Renderer::css() !!}</style></head><body><header><a class="brand" href="{{ $urls['home'] }}">◈ {{ $site->name }}</a><nav><a href="{{ $urls['home'] }}">首页</a><a href="{{ $urls['list'] }}">影片索引</a></nav><form action="{{ $urls['search'] }}"><input name="q" value="{{ request('q') }}" aria-label="搜索影片" placeholder="搜索影片…"><button>搜索</button></form></header><main><section class="catalog-head"><div class="eyebrow">电影 · 剧集 · 资料库</div><h1>{{ $slots['h1'] ?? $site->name }}</h1><p>{!! $slots['intro'] ?? ($hasSeoBundle ? '' : (request('q') ? '搜索结果来自已发布的影片资料。' : '电影、剧集与创作者的完整资料索引。')) !!}</p><p>{{ $movies->total() }} 部已发布影片</p></section>@if($hasSeoBundle)@foreach($slots as $slot => $value)@if(str_starts_with($slot, 'h2.'))<h2 id="{{ substr($slot, 3) }}">{{ $value }}</h2>@endif @endforeach @endif<div class="grid">@forelse($movies as $movie)@php($snapshot = json_decode($movie->snapshot_json,true))@php($content = $snapshot['content'] ?? [])@php($poster = $content['poster_url'] ?? $content['metadata']['poster_url'] ?? null)<a class="card" href="{{ $movie->canonical_path }}">@if($poster && App\Domain\Rules\Html::safeUrl($poster))<img src="{{ $poster }}" alt="{{ $content['title'] ?? '' }}" loading="lazy">@else<div class="placeholder">◈</div>@endif<h2>{{ $content['title'] ?? $snapshot['slots']['h1'] ?? '影片资料' }}</h2><p>{{ $content['year'] ?? '' }} · {{ $content['genre'] ?? '' }}</p></a>@empty<p>暂无已发布影片。请先导入内容、预览并发布。</p>@endforelse</div><div style="margin-top:35px">@if($movies